import { isOptionAttribute } from "../../schema";
import type { Attr } from "./builders";

/**
 * Sprint 2-D.1 (TD-03) — visual examples for options, using the EXISTING `examples` metadata (no new
 * schema, no separate visual data): static SVG line art in public/visual (loaded lazily by the card
 * control), generated by scripts/generate-visual-assets.mjs. These attributes use the `cards` control;
 * values, IDs and prompt output are unchanged.
 */
/**
 * `options`: only these options have a drawing (representative subset of a large list); the attribute keeps
 * its searchable list and shows a thumbnail next to drawn options (Sprint 2-D.3). Without `options` every
 * option has a drawing and the attribute uses the `cards` control. Several attributes may share a folder
 * (same option ids, same meaning, e.g. top and one-piece necklines).
 */
export interface VisualAssetDir {
  dir: string;
  noun: { en: string; ko: string };
  options?: readonly string[];
}
const N = (en: string, ko: string) => ({ en, ko });
